public class TurnstileTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Turnstile t = new Turnstile();
        check("starts locked", "locked", t.state());
        t.coin();
        check("coin unlocks", "unlocked", t.state());
        t.coin();
        check("extra coin changes nothing", "unlocked", t.state());
        t.push();
        check("push relocks", "locked", t.state());
        t.push();
        check("push while locked stays locked", "locked", t.state());
        check("blocked push was counted", 1, t.blockedCount());
        t.push();
        t.push();
        check("blocked count accumulates", 3, t.blockedCount());
        t.coin();
        t.push();
        check("a normal pass is not counted as blocked", 3, t.blockedCount());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

