public class Turnstile {

    private boolean locked = true;
    private int blocked = 0;

    public String state() {
        return locked ? "locked" : "unlocked";
    }

    public void coin() {
        locked = false;
    }

    public void push() {
        if (locked) {
            blocked++;
        } else {
            locked = true;
        }
    }

    public int blockedCount() {
        return blocked;
    }
}
